import java.util.*;

class Solution {
    private int[] parent;

    public int[] extraCable(int[][] edges) {
        int n = edges.length;
        parent = new int[n + 1]; // labels are 1..n
        for (int i = 0; i <= n; i++) parent[i] = i;
        for (int[] e : edges) {
            int ra = find(e[0]), rb = find(e[1]);
            if (ra == rb) return e; // already connected: this cable closes the loop
            parent[ra] = rb;
        }
        return new int[0];
    }

    private int find(int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]]; // path compression
            x = parent[x];
        }
        return x;
    }
}

