class Solution:
    def extraCable(self, edges: List[List[int]]) -> List[int]:
        p = list(range(len(edges) + 1))
        def f(x):
            while p[x] != x: p[x] = p[p[x]]; x = p[x]
            return x
        for a, b in edges:
            ra, rb = f(a), f(b)
            if ra == rb: return [a, b]
            p[ra] = rb

