function extraCable(edges) {
  // leaf peeling: strip degree-1 nodes until only the cycle is left (independent of union-find)
  const n = edges.length, deg = new Array(n + 1).fill(0), g = Array.from({length: n + 1}, () => []);
  for (const [a, b] of edges) { deg[a]++; deg[b]++; g[a].push(b); g[b].push(a); }
  const st = []; for (let v = 1; v <= n; v++) if (deg[v] === 1) st.push(v);
  while (st.length) { const v = st.pop(); deg[v] = 0; for (const u of g[v]) if (deg[u] > 0 && --deg[u] === 1) st.push(u); }
  for (let i = n - 1; i >= 0; i--) { const [a, b] = edges[i]; if (deg[a] > 1 && deg[b] > 1) return edges[i]; }
}
